import { GRID_SIZES, MAX_SEED, type GridSize } from "./constants.ts";
import { generateDeck } from "./deck.ts";
import type { BoardDescription } from "./state.ts";

const CODE_PATTERN = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/;

export function isGridSize(value: unknown): value is GridSize {
  return typeof value === "number" && GRID_SIZES.some((size) => size === value);
}

export function parseBoardCode(value: string): BoardDescription | null {
  const match = CODE_PATTERN.exec(value);
  if (!match) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isGridSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return { code: value, size, seed };
}

export function createBoard(value: string): { board: BoardDescription; deck: readonly number[] } | null {
  const board = parseBoardCode(value);
  return board ? { board, deck: generateDeck(board.size, board.seed) } : null;
}

import { SELECTION_KIND, type GridSize } from "./constants.ts";

export type BoardDescription = Readonly<{
  code: string;
  size: GridSize;
  seed: number;
}>;

export type Selection =
  | Readonly<{ kind: typeof SELECTION_KIND.closed }>
  | Readonly<{ kind: typeof SELECTION_KIND.one; index: number }>
  | Readonly<{
      kind: typeof SELECTION_KIND.mismatch;
      first: number;
      second: number;
      remainingMs: number;
    }>;

export type GameState = Readonly<{
  board: BoardDescription;
  deck: readonly number[];
  matched: readonly number[];
  selection: Selection;
  moves: number;
  elapsedMs: number;
  started: boolean;
}>;

export const CLOSED_SELECTION: Selection = { kind: SELECTION_KIND.closed };

export function pairCount(state: GameState): number {
  return state.matched.length / 2;
}
import { MAX_ELAPSED_MS, MAX_MOVES, MISMATCH_MS, SELECTION_KIND } from "./constants.ts";
import { createBoard } from "./boardCode.ts";
import { CLOSED_SELECTION, type GameState } from "./state.ts";

export function createGame(boardCode: string): GameState | null {
  const created = createBoard(boardCode);
  if (!created) return null;
  return {
    ...created,
    matched: [],
    selection: CLOSED_SELECTION,
    moves: 0,
    elapsedMs: 0,
    started: false,
  };
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

function addMove(moves: number): number {
  return Math.min(MAX_MOVES, moves + 1);
}

export function activateCard(state: GameState, index: number): GameState {
  if (isWon(state) || !Number.isInteger(index) || index < 0 || index >= state.deck.length) return state;
  if (state.matched.includes(index) || state.selection.kind === SELECTION_KIND.mismatch) return state;

  const selection = state.selection;
  if (selection.kind === SELECTION_KIND.closed) {
    return { ...state, selection: { kind: SELECTION_KIND.one, index }, started: true };
  }
  if (selection.index === index) return state;

  const moves = addMove(state.moves);
  if (state.deck[selection.index] === state.deck[index]) {
    return {
      ...state,
      matched: [...state.matched, selection.index, index],
      selection: CLOSED_SELECTION,
      moves,
      started: true,
    };
  }
  return {
    ...state,
    selection: { kind: SELECTION_KIND.mismatch, first: selection.index, second: index, remainingMs: MISMATCH_MS },
    moves,
    started: true,
  };
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  if (state.selection.kind !== SELECTION_KIND.mismatch) return { ...state, elapsedMs };

  const remainingMs = state.selection.remainingMs - milliseconds;
  if (remainingMs <= 0) return { ...state, elapsedMs, selection: CLOSED_SELECTION };
  return { ...state, elapsedMs, selection: { ...state.selection, remainingMs } };
}

export function formatTime(elapsedMs: number): string {
  const totalSeconds = Math.floor(Math.max(0, elapsedMs) / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = String(totalSeconds % 60).padStart(2, "0");
  return `${minutes}:${seconds}`;
}
import { MAX_ELAPSED_MS, MAX_MOVES, MAX_SNAPSHOT_BYTES, MISMATCH_MS, SELECTION_KIND, SNAPSHOT_KEYS } from "./constants.ts";
import { createGame } from "./transition.ts";
import type { GameState, Selection } from "./state.ts";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function hasKeys(value: Record<string, unknown>, expected: readonly string[]): boolean {
  const actual = Object.keys(value);
  return actual.length === expected.length && actual.every((key) => expected.includes(key));
}

function safeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function inRangeIndex(value: unknown, length: number): value is number {
  return safeInteger(value) && value < length;
}

function decodeSelection(value: unknown, state: GameState, matched: Set<number>): Selection | null {
  if (!isRecord(value) || typeof value.kind !== "string") return null;
  if (value.kind === SELECTION_KIND.closed) return hasKeys(value, ["kind"]) ? { kind: SELECTION_KIND.closed } : null;
  if (value.kind === SELECTION_KIND.one) {
    return hasKeys(value, ["kind", "index"]) && inRangeIndex(value.index, state.deck.length) && !matched.has(value.index)
      ? { kind: SELECTION_KIND.one, index: value.index }
      : null;
  }
  if (value.kind === SELECTION_KIND.mismatch) {
    const keysValid = hasKeys(value, ["kind", "first", "second", "remainingMs"]);
    if (!keysValid || !inRangeIndex(value.first, state.deck.length) || !inRangeIndex(value.second, state.deck.length)) return null;
    if (value.first === value.second || matched.has(value.first) || matched.has(value.second)) return null;
    if (state.deck[value.first] === state.deck[value.second]) return null;
    if (!safeInteger(value.remainingMs) || value.remainingMs < 1 || value.remainingMs > MISMATCH_MS) return null;
    return { kind: SELECTION_KIND.mismatch, first: value.first, second: value.second, remainingMs: value.remainingMs };
  }
  return null;
}

function containsWholePairs(matched: readonly number[], deck: readonly number[]): boolean {
  const positions = new Set(matched);
  if (positions.size !== matched.length || matched.some((index) => !inRangeIndex(index, deck.length))) return false;
  return matched.every((index) => deck.every((face, other) => face !== deck[index] || positions.has(other)));
}

export function encodeSnapshot(state: GameState): string {
  const selection = state.selection.kind === SELECTION_KIND.mismatch
    ? { ...state.selection, remainingMs: Math.max(1, Math.floor(state.selection.remainingMs)) }
    : state.selection;
  return JSON.stringify({
    version: 1,
    boardCode: state.board.code,
    matched: state.matched,
    selection,
