import { useEffect, useRef, useState } from "react";
import { GRID_SIZES, SELECTION_KIND, type GridSize } from "../constants.ts";
import { isGridSize } from "../boardCode.ts";
import { createGame, activateCard, advanceGame, formatTime, isWon } from "../transition.ts";
import { decodeSnapshot, encodeSnapshot } from "../snapshot.ts";
import type { GameState } from "../state.ts";
import { readPreferences, saveBest, saveSize } from "./storage.ts";
import { newSeed } from "./randomSeed.ts";

export type Announcement = Readonly<{ id: number; text: string }>;
export type SessionView = Readonly<{
  game: GameState;
  paused: boolean;
  generation: number;
  best: number | null;
  announcement: Announcement | null;
  celebration: number;
}>;

function initialView(): SessionView {
  const preferences = readPreferences();
  const size = preferences.size;
  const game = createGame(`np1-${size}-${newSeed()}`);
  if (!game) throw new Error("Unable to create a starting board.");
  return { game, paused: false, generation: 0, best: preferences.bests[size] ?? null, announcement: null, celebration: 0 };
}

export function useGameSession() {
  const [view, setView] = useState(initialView);
  const viewRef = useRef(view);
  const bestsRef = useRef(readPreferences().bests);
  const announcementId = useRef(0);
  const lastTime = useRef(performance.now());
  const activeClock = useRef(!document.hidden);

  function commit(next: SessionView): void {
    viewRef.current = next;
    setView(next);
  }

  function announce(text: string): Announcement {
    announcementId.current += 1;
    return { id: announcementId.current, text };
  }

  function advanceClock(now: number): GameState {
    const delta = Math.max(0, now - lastTime.current);
    lastTime.current = now;
    const current = viewRef.current;
    if (!activeClock.current || !current.game.started || isWon(current.game)) return current.game;
    const game = advanceGame(current.game, delta);
    if (game !== current.game) commit({ ...current, game });
    if (isWon(game)) activeClock.current = false;
    return game;
  }

  useEffect(() => {
    lastTime.current = performance.now();
    activeClock.current = !document.hidden && !viewRef.current.paused && !isWon(viewRef.current.game);
    const timer = window.setInterval(() => advanceClock(performance.now()), 50);
    const visibilityChange = (): void => {
      const now = performance.now();
      advanceClock(now);
      activeClock.current = !document.hidden && !viewRef.current.paused && !isWon(viewRef.current.game);
      lastTime.current = now;
    };
    document.addEventListener("visibilitychange", visibilityChange);
    return () => {
      window.clearInterval(timer);
      document.removeEventListener("visibilitychange", visibilityChange);
      activeClock.current = false;
    };
  }, []);

  function replaceGame(game: GameState, paused: boolean, status: string | null): void {
    const now = performance.now();
    lastTime.current = now;
    activeClock.current = !document.hidden && !paused && !isWon(game);
    saveSize(game.board.size);
    commit({
      game,
      paused,
      generation: viewRef.current.generation + 1,
      best: bestsRef.current[game.board.size] ?? null,
      announcement: status === null ? null : announce(status),
      celebration: viewRef.current.celebration,
    });
  }

  function freshGame(size: GridSize, current: GameState): GameState {
    const seed = newSeed(current.board.seed);
    const game = createGame(`np1-${size}-${seed}`);
    if (!game) throw new Error("Unable to create a board for a supported size.");
    return game;
  }

  function activate(index: number): void {
    const before = advanceClock(performance.now());
    if (viewRef.current.paused) return;
    const next = activateCard(before, index);
    if (next === before) return;
    const turnEnded = before.selection.kind === SELECTION_KIND.one;
    const completedNow = !isWon(before) && isWon(next);
    const text = turnEnded
      ? next.selection.kind === SELECTION_KIND.mismatch
        ? "No match. Cards close after a short pause."
        : completedNow
          ? `Pair found. All pairs found in ${next.moves} moves and ${formatTime(next.elapsedMs)}.`
          : `Pair found. ${next.matched.length / 2} ${next.matched.length === 2 ? "pair" : "pairs"} matched.`
      : null;
    let best = viewRef.current.best;
    if (completedNow) {
      const recorded = bestsRef.current[next.board.size];
      if (recorded === undefined || next.moves < recorded) {
        bestsRef.current = { ...bestsRef.current, [next.board.size]: next.moves };
        best = next.moves;
        saveBest(next.board.size, next.moves);
      }
    }
    if (isWon(next)) activeClock.current = false;
    commit({
      ...viewRef.current,
      game: next,
      best,
      announcement: text === null ? viewRef.current.announcement : announce(text),
      celebration: completedNow ? viewRef.current.celebration + 1 : viewRef.current.celebration,
    });
  }

  function startNew(): void {
    const current = viewRef.current.game;
    replaceGame(freshGame(current.board.size, current), false, null);
  }

  function restart(): void {
    const game = createGame(viewRef.current.game.board.code);
    if (game) replaceGame(game, false, null);
  }

  function changeSize(value: string): void {
    const size = Number(value);
    if (!isGridSize(size) || size === viewRef.current.game.board.size) return;
    replaceGame(freshGame(size, viewRef.current.game), false, null);
  }

  function loadBoard(draft: string): void {
    const game = createGame(draft.trim());
    if (!game) {
      commit({ ...viewRef.current, announcement: announce("Invalid board code.") });
      return;
    }
    replaceGame(game, false, null);
  }

  function snapshot(): string {
    return encodeSnapshot(advanceClock(performance.now()));
  }

  function loadSnapshot(text: string): void {
    const game = decodeSnapshot(text);
    if (!game) {
      commit({ ...viewRef.current, announcement: announce("Invalid snapshot.") });
      return;
    }
    const complete = isWon(game);
    replaceGame(game, !complete, complete ? "Loaded completed snapshot." : "Loaded snapshot. Select Resume to continue.");
  }

  function resume(): void {
    const current = viewRef.current;
    if (!current.paused) return;
    lastTime.current = performance.now();
    activeClock.current = !document.hidden && !isWon(current.game);
    commit({ ...current, paused: false });
  }

  return {
    view,
    actions: { activate, startNew, restart, changeSize, loadBoard, snapshot, loadSnapshot, resume },
    sizes: GRID_SIZES,
  } as const;
}
import { forwardRef, useImperativeHandle, useRef, useState } from "react";
import type { CSSProperties } from "react";
import type { KeyboardEvent } from "react";
import { SELECTION_KIND } from "../constants.ts";
import { isWon } from "../transition.ts";
import type { GameState } from "../state.ts";
import { CardBack, FaceArtwork, faceName } from "./Artwork.tsx";
import "./Board.css";

export type BoardHandle = Readonly<{ focusRemembered: () => void }>;
type Props = Readonly<{ game: GameState; paused: boolean; onActivate: (index: number) => void }>;

export const Board = forwardRef<BoardHandle, Props>(function Board({ game, paused, onActivate }, ref) {
  const [focused, setFocused] = useState(0);
  const buttons = useRef(new Map<number, HTMLButtonElement>());
  const suppressedKeyboardClick = useRef(false);
  const columns = game.board.size;
  const gridStyle: CSSProperties & { "--columns": number; "--card-size": string } = {
    "--columns": columns,
    "--card-size": `clamp(44px, calc((100cqw - ${(columns - 1) * 6}px) / ${columns}), 88px)`,
  };
  const shown = (index: number): boolean => game.matched.includes(index)
    || game.selection.kind === SELECTION_KIND.one && game.selection.index === index
    || game.selection.kind === SELECTION_KIND.mismatch && (game.selection.first === index || game.selection.second === index);

  function focusCard(index: number): void {
    setFocused(index);
    const button = buttons.current.get(index);
    button?.focus();
    button?.scrollIntoView({ block: "nearest", inline: "nearest" });
  }

  useImperativeHandle(ref, () => ({ focusRemembered: () => focusCard(focused) }), [focused]);

  function onKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number): void {
    if ((event.key === "Enter" || event.key === " ") && (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey)) {
      suppressedKeyboardClick.current = true;
      return;
    }
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const row = Math.floor(index / columns);
    const column = index % columns;
    const target = event.key === "ArrowLeft" && column > 0 ? index - 1
      : event.key === "ArrowRight" && column < columns - 1 ? index + 1
        : event.key === "ArrowUp" && row > 0 ? index - columns
          : event.key === "ArrowDown" && row < columns - 1 ? index + columns
            : null;
    if (target !== null) {
      event.preventDefault();
      focusCard(target);
    } else if (["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.key)) {
      event.preventDefault();
    }
  }

  const total = columns * columns;
  return (
    <div className="board-scroll" aria-label="Memory game board">
      <div className="board-grid" style={gridStyle}>
        {Array.from({ length: total }, (_, index) => {
          const faceShown = shown(index);
          const matched = game.matched.includes(index);
          const face = faceShown ? game.deck[index] : undefined;
          const row = Math.floor(index / columns) + 1;
          const column = index % columns + 1;
          const label = face === undefined ? `Row ${row}, column ${column}, closed`
            : `Row ${row}, column ${column}, ${faceName(face)}, ${matched ? "matched" : "revealed"}`;
          return (
            <button
              key={index}
              ref={(node) => { if (node) buttons.current.set(index, node); else buttons.current.delete(index); }}
              type="button"
              className={`card${faceShown ? " card--face" : ""}${matched ? " card--matched" : ""}`}
              tabIndex={focused === index ? 0 : -1}
              aria-label={label}
              aria-disabled={matched ? "true" : undefined}
              onFocus={() => { setFocused(index); buttons.current.get(index)?.scrollIntoView({ block: "nearest", inline: "nearest" }); }}
              onKeyDown={(event) => onKeyDown(event, index)}
              onKeyUp={(event) => {
                if ((event.key === "Enter" || event.key === " ") && suppressedKeyboardClick.current) {
                  window.setTimeout(() => { suppressedKeyboardClick.current = false; }, 0);
                }
              }}
              onClick={(event) => {
                if (event.detail === 0 && suppressedKeyboardClick.current) {
                  suppressedKeyboardClick.current = false;
                  return;
                }
                if (event.detail === 0 && (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey)) return;
                if (!paused && !isWon(game)) onActivate(index);
              }}
            >
              {face === undefined ? <CardBack /> : <FaceArtwork id={face} />}
              {matched && <span className="match-check" aria-hidden="true">✓</span>}
            </button>
          );
        })}
      </div>
    </div>
  );
});
.board-scroll {
  container-type: inline-size;
  max-height: min(70dvh, 768px);
  overflow: auto;
  padding: 6px;
  border-radius: 12px;
  background: #141827;
  overscroll-behavior: contain;
}

.board-grid {
  display: grid;
  width: max-content;
  grid-template-columns: repeat(var(--columns), var(--card-size));
  gap: 6px;
}

.card {
  position: relative;
  display: grid;
  place-items: center;
  width: var(--card-size);
  aspect-ratio: 1;
  padding: 4px;
  border: 2px solid #757c9a;
  border-radius: 8px;
  background: #1b2034;
  color: #f4f6ff;
  cursor: pointer;
  scroll-margin: 8px;
  transition: border-color 120ms ease;
}

.card--face {
  background: #111625;
}

.card--matched {
  border-color: #8bea7d;
}

.card:hover {
  border-color: #f4f6ff;
}

.card--matched:hover {
  border-color: #8bea7d;
}

.card:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
  z-index: 1;
}

.face-artwork,
.card-back {
  display: block;
  width: 100%;
  height: 100%;
}

.match-check {
  position: absolute;
  right: 4px;
  bottom: 4px;
  color: #8bea7d;
  font-size: 14px;
  font-weight: 700;
  line-height: 1;
}

@media (prefers-reduced-motion: reduce) {
  .card { transition: none; }
}

