import { mkdir, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { expect, test } from "@playwright/test";
import { cardButtons, deckFor, offlineHtmlUrl, pairsFor, REPLAYABLE_CODE } from "./support.ts";

async function moveWithArrows(page: import("@playwright/test").Page, from: number, to: number, columns: number): Promise<void> {
  let current = from;
  while (current % columns < to % columns) {
    await page.keyboard.press("ArrowRight");
    current += 1;
  }
  while (current % columns > to % columns) {
    await page.keyboard.press("ArrowLeft");
    current -= 1;
  }
  while (Math.floor(current / columns) < Math.floor(to / columns)) {
    await page.keyboard.press("ArrowDown");
    current += columns;
  }
  while (Math.floor(current / columns) > Math.floor(to / columns)) {
    await page.keyboard.press("ArrowUp");
    current -= columns;
  }
}

