import { chromium } from '@playwright/test';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';

const boardCode = 'np1-4-1';
function deck(size, seed) {
  const modulus = 2147483647;
  const rangeSize = modulus - 1;
  const state = { value: seed };
  const values = Array.from({ length: size * size }, (_, index) => Math.floor(index / 2));
  for (let index = values.length - 1; index > 0; index -= 1) {
    const bound = index + 1;
    const limit = Math.floor(rangeSize / bound) * bound;
    let draw;
    do {
      state.value = (state.value * 16807) % modulus;
      draw = state.value - 1;
    } while (draw >= limit);
    const other = draw % bound;
    [values[index], values[other]] = [values[other], values[index]];
  }
  const positions = new Map();
  values.forEach((face, position) => positions.set(face, [...(positions.get(face) ?? []), position]));
  return [...positions.values()];
}
async function playToWin(page) {
  await page.goto(pathToFileURL(resolve('dist/index.html')).href);
