const commands = [
  ["git", "git status --short"],
  ["dist", "find dist -maxdepth 2 -type f -printf '%p %s bytes\\n'"],
  ["assets", "rg -n '<(script|link|img|source|iframe)[^>]+(src|href)=' dist/index.html"],
  ["lines", "wc -l src/game/*.ts src/game/*.tsx src/game/**/*.ts src/game/**/*.tsx scripts/*.ts e2e/*.ts"],
  ["unsafe", "rg -n '\\bany\\b|@ts-ignore|@ts-expect-error| as [A-Z]' src scripts e2e"],
  ["processes", "ps -eo pid,args | rg 'vite (preview|--host)|node .*vite|playwright'"],
];
const results = await Promise.allSettled(commands.map(async ([name, cmd]) => {
  const r = await tools.exec_command({cmd, workdir:"/work", yield_time_ms:10000, max_output_tokens:2000});
  return {name, ...r};
}));
for (const r of results) text(JSON.stringify(r));
